import React, { useState, useEffect } from 'react';
import { TrendingUp, Sparkles } from 'lucide-react';

const WelcomeBanner = () => {
  const [currentTime, setCurrentTime] = useState('');

  useEffect(() => {
    const updateTime = () => {
      const now = new Date();
      setCurrentTime(now.toLocaleTimeString('fr-FR', { 
        hour: '2-digit', 
        minute: '2-digit' 
      }));
    };

    updateTime();
    const interval = setInterval(updateTime, 60000);

    return () => clearInterval(interval);
  }, []);

  const greetings = [
    "Bon retour, Enzo ! 👋",
    "Bonne journée, Enzo ! 🌟",
    "Ravi de vous revoir, Enzo ! 🚀"
  ];
  const [greeting, setGreeting] = useState(greetings[0]);

  useEffect(() => {
    const interval = setInterval(() => {
      setGreeting(prev => {
        const currentIndex = greetings.indexOf(prev);
        const nextIndex = (currentIndex + 1) % greetings.length;
        return greetings[nextIndex];
      });
    }, 5000);

    return () => clearInterval(interval);
  }, []);

  return (
    <div className="mb-6 sm:mb-8 rounded-2xl bg-gradient-to-r from-primary-500 via-primary-600 to-secondary-500 p-4 sm:p-6 text-white shadow-lg relative overflow-hidden animate-fade-in group hover:shadow-xl transition-all duration-300">
      {/* Effet de brillance */}
      <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/10 to-transparent -translate-x-full group-hover:translate-x-full transition-transform duration-1000" />

      {/* Particules flottantes */}
      <div className="absolute inset-0 overflow-hidden">
        {[...Array(5)].map((_, i) => (
          <div
            key={i}
            className="absolute w-1 h-1 bg-white/30 rounded-full animate-float"
            style={{
              left: `${Math.random() * 100}%`,
              top: `${Math.random() * 100}%`,
              animationDelay: `${i * 0.5}s`,
            }}
          />
        ))}
      </div>

      <div className="flex flex-col gap-4 md:flex-row md:items-center md:justify-between relative z-10">
        <div className="space-y-2">
          <div className="flex items-center gap-2">
            <h1 className="text-xl sm:text-2xl font-bold transition-all duration-500 ease-in-out transform group-hover:translate-x-1">
              {greeting}
            </h1>
            <Sparkles className="h-5 w-5 text-yellow-300 animate-pulse-gentle" />
          </div>
          <p className="text-sm sm:text-base opacity-90 animate-slide-up">
            Voici ce qui se passe dans votre boutique aujourd'hui.
          </p>

          {/* Stat rapide */}
          <div className="flex items-center gap-2 mt-2 animate-slide-in" style={{animationDelay: '0.2s'}}>
            <TrendingUp className="h-4 w-4" />
            <span className="text-xs sm:text-sm bg-white/20 px-2 py-1 rounded-lg backdrop-blur-sm">
              +12% de croissance cette semaine
            </span>
          </div>
        </div>

        <div className="flex flex-col sm:flex-row items-stretch sm:items-center gap-2">
          <div className="px-3 sm:px-4 py-2 bg-white/20 rounded-xl backdrop-blur-sm order-2 sm:order-1 border border-white/30 hover:bg-white/30 transition-all duration-300 animate-slide-up" style={{animationDelay: '0.3s'}}>
            <div className="flex items-center gap-2">
              <div className="w-2 h-2 bg-green-400 rounded-full animate-pulse" />
              <span className="text-xs sm:text-sm font-medium">
                Dernière connexion : {currentTime}
              </span>
            </div>
          </div>

          <button className="px-3 sm:px-4 py-2 bg-white text-primary-600 font-medium rounded-xl hover:bg-white/90 transition-all duration-300 hover:scale-[1.02] active:scale-[0.98] shadow-lg hover:shadow-xl flex items-center justify-center gap-2 order-1 sm:order-2 animate-slide-up" style={{animationDelay: '0.4s'}}>
            <TrendingUp className="h-4 w-4" />
            Voir rapport détaillé
          </button>
        </div>
      </div>
    </div>
  );
};

export default WelcomeBanner;
